mapper.select:
SELECT (
        SELECT  COUNT(*)
          FROM  tdm43_manl
         WHERE  tdm43_task_relate_detail_id = #{taskDetailId}
       ) + (
        SELECT  COUNT(*)
          FROM  tdm35_role_allc_task
                INNER JOIN tdm34_role_allc_detail ON tdm34_role_allc_detail_id = tdm35_role_allc_detail_id
                INNER JOIN apr01_appr             ON (    apr01_appr_id = tdm34_appr_id
                                                      AND COALESCE(apr01_status_cd,'99') IN ('10','20','30') )
         WHERE  tdm35_task_relate_detail_id = #{taskDetailId}
       )

mapper.update:
UPDATE tdm12_task_relate_detail
   SET tdm12_content = #{row.content}
     , tdm12_seq     = #{row.seq}
     , tdm12_use_yn  = #{row.useYn}
     , tdm12_upd_nm  = #{updName}
     , tdm12_upd_date = f_sysdate()
 WHERE tdm12_task_relate_detail_id = #{row.taskRelateDetailId}

mapper.delete:
DELETE FROM tdm12_task_relate_detail
 WHERE tdm12_task_relate_detail_id IN
#{id}
